const { createHourlyLimit } = require('./throttle');

function validateUser(user) {
  if (!user || typeof user !== 'object') {
    throw new TypeError('user is required');
  }
  if (!user.id) {
    throw new TypeError('user.id is required');
  }
}

function validateMessage(message) {
  if (!message || typeof message !== 'object') {
    throw new TypeError('message is required');
  }
  if (!message.title || !message.body) {
    throw new TypeError('message.title and message.body are required');
  }
}

function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

/**
 * Builds a notifier for one channel from a channel definition:
 *
 * - channel: channel name, also the transport method that delivers the payload
 * - transportName: how delivery errors name the transport
 * - defaultMaxPerHour: hourly limit used when options.maxPerHour is not set
 * - resolveSettings(options): channel-specific settings, passed to format()
 * - validateUser(user): channel checks, run after the shared user checks
 * - isThrottleExempt(message, sendOptions): optional; true skips all throttling
 * - checkConsent(user, message): optional; runs after the hourly limit passes
 *   and returns null or { reason, retryAt }
 * - format(base, { user, message, sendOptions, settings, now }): channel fields,
 *   merged over the shared base payload before delivery
 *
 * The returned notifier's send() never reads `this`, so it can be detached.
 */
function createChannelNotifier(definition, options) {
  const { channel } = definition;
  const transport = options.transport || {};
  const now = options.now || (() => new Date());
  const defaultLocale = options.defaultLocale || 'en-US';
  const settings = definition.resolveSettings(options);
  const hourlyLimit = createHourlyLimit({
    channel,
    store: options.throttleStore || new Map(),
    now,
    maxPerHour: options.maxPerHour || definition.defaultMaxPerHour
  });

  function checkThrottle(user, message, sendOptions) {
    if (definition.isThrottleExempt && definition.isThrottleExempt(message, sendOptions)) {
      return null;
    }
    const limited = hourlyLimit.check(user, message, sendOptions);
    if (limited || !definition.checkConsent) {
      return limited;
    }
    return definition.checkConsent(user, message);
  }

  function formatBase(user, message, sendOptions) {
    const id = `${channel}-${user.id}-${now().getTime()}`;
    const locale = sendOptions.locale || user.locale || defaultLocale;
    const title = applyTemplate(message.title, user, message);
    const body = applyTemplate(message.body, user, message);

    return {
      id,
      channel,
      locale,
      title,
      body,
      preview: `${title}: ${body}`.slice(0, 120),
      metadata: {
        category: message.category || 'general',
        priority: message.priority || 'normal',
        generatedAt: now().toISOString()
      }
    };
  }

  async function deliver(payload) {
    if (typeof transport[channel] !== 'function') {
      throw new Error(`${definition.transportName} transport is not configured`);
    }
    // Called as a method so transports that rely on `this` keep working.
    await transport[channel](payload);
  }

  async function send(user, message, sendOptions = {}) {
    validateUser(user);
    definition.validateUser(user);
    validateMessage(message);

    const throttled = checkThrottle(user, message, sendOptions);
    if (throttled) {
      return {
        channel,
        status: 'throttled',
        reason: throttled.reason,
        retryAt: throttled.retryAt,
        userId: user.id
      };
    }

    const base = formatBase(user, message, sendOptions);
    const payload = {
      ...base,
      ...definition.format(base, { user, message, sendOptions, settings, now })
    };
    await deliver(payload);
    hourlyLimit.record(user, message);

    return {
      channel,
      status: 'sent',
      userId: user.id,
      id: payload.id,
      preview: payload.preview
    };
  }

  return { channel, send };
}

module.exports = {
  createChannelNotifier
};
