const { requireMarketingOptIn } = require('./throttle');

const E164_PATTERN = /^\+[1-9]\d{6,14}$/;

function truncate(value, segmentLength) {
  if (value.length <= segmentLength) {
    return value;
  }
  return `${value.slice(0, segmentLength - 1)}…`;
}

const smsChannel = {
  channel: 'sms',
  transportName: 'sms',
  defaultMaxPerHour: 4,

  resolveSettings(options) {
    return {
      senderId: options.senderId || 'APP',
      segmentLength: options.segmentLength || 140
    };
  },

  validateUser(user) {
    if (!user.phone || !E164_PATTERN.test(user.phone)) {
      throw new TypeError('user.phone must be E.164 for SMS notifications');
    }
  },

  checkConsent: requireMarketingOptIn('smsOptIn', 'SMS'),

  format(base, { user, message, settings }) {
    const prefix = message.priority === 'urgent' ? 'URGENT: ' : '';
    const text = truncate(`${prefix}${base.title} - ${base.body}`, settings.segmentLength);

    return {
      to: user.phone,
      from: settings.senderId,
      text,
      segments: Math.ceil(text.length / settings.segmentLength),
      preview: text
    };
  }
};

function createSmsNotifier(options = {}) {
  return createChannelNotifier(smsChannel, options);
}

module.exports = {
  createSmsNotifier
};
