function blocksFor(base, mention) {
  return [
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `${mention}*${base.title}*`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: base.body
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `Category: ${base.metadata.category}`
        }
      ]
    }
  ];
}

const slackChannel = {
  channel: 'slack',
  transportName: 'slack',
  defaultMaxPerHour: 20,

  resolveSettings(options) {
    return {
      defaultWorkspace: options.defaultWorkspace || 'main',
      defaultChannel: options.defaultChannel || '#general'
    };
  },

  validateUser(user) {
    if (!user.slackId && !user.slackChannel) {
      throw new TypeError('user.slackId or user.slackChannel is required for Slack notifications');
    }
  },

  isThrottleExempt(message, sendOptions) {
    return Boolean(sendOptions.threadTs);
  },

  format(base, { user, sendOptions, settings }) {
    const mention = user.slackId ? `<@${user.slackId}> ` : '';
    const text = `${mention}*${base.title}*\n${base.body}`;

    // `channel` here is the Slack destination and replaces the base payload's channel name.
    return {
      workspace: user.slackWorkspace || settings.defaultWorkspace,
      channel: sendOptions.channel || user.slackChannel || settings.defaultChannel,
      threadTs: sendOptions.threadTs || null,
      text,
      blocks: blocksFor(base, mention),
      preview: text.replace(/\*/g, '').slice(0, 120)
    };
  }
};

function createSlackNotifier(options = {}) {
  return createChannelNotifier(slackChannel, options);
}

module.exports = {
  createSlackNotifier
};
const { createEmailNotifier } = require('./email');
const { createSmsNotifier } = require('./sms');
const { createSlackNotifier } = require('./slack');
const { createInAppNotifier } = require('./inapp');

// Entries are plain function factories, so both registry.email(options) and
// the older `new registry.email(options)` return a notifier.
const registry = {
  email: createEmailNotifier,
  sms: createSmsNotifier,
  slack: createSlackNotifier,
  inapp: createInAppNotifier
};

function createNotifier(channel, options = {}) {
  // Own keys only: inherited names such as "constructor" are not channels.
  if (!Object.hasOwn(registry, channel)) {
    throw new TypeError(`unknown notification channel: ${channel}`);
  }
  return registry[channel](options);
}

function createAllNotifiers(options = {}) {
  return Object.keys(registry).reduce((all, channel) => {
    all[channel] = createNotifier(channel, options);
    return all;
  }, {});
}

module.exports = {
  createNotifier,
  createAllNotifiers,
  registry
};

