const { createChannelNotifier } = require('./channelNotifier');

const HOUR_MS = 60 * 60 * 1000;
const URGENT_EXPIRY_HOURS = 72;
const DEFAULT_EXPIRY_HOURS = 168;

const inAppChannel = {
  channel: 'inapp',
  transportName: 'in-app',
  defaultMaxPerHour: 50,

  resolveSettings(options) {
    return {
      defaultIcon: options.defaultIcon || 'bell',
      defaultAction: options.defaultAction || '/notifications'
    };
  },

  validateUser(user) {
    if (user.disabledInApp) {
      throw new TypeError('in-app notifications are disabled for this user');
    }
  },

  isThrottleExempt(message) {
    return message.category === 'security';
  },

  format(base, { user, message, sendOptions, settings, now }) {
    const expiresInHours = sendOptions.expiresInHours
      || (message.priority === 'urgent' ? URGENT_EXPIRY_HOURS : DEFAULT_EXPIRY_HOURS);
    const expiresAt = new Date(now().getTime() + expiresInHours * HOUR_MS);

    return {
      userId: user.id,
      icon: message.icon || settings.defaultIcon,
      actionUrl: sendOptions.actionUrl || message.actionUrl || settings.defaultAction,
      read: false,
      expiresAt: expiresAt.toISOString(),
      preview: base.title
    };
  }
};

function createInAppNotifier(options = {}) {
  return createChannelNotifier(inAppChannel, options);
}

module.exports = {
  createInAppNotifier
};
