    for (const [channel, factory] of Object.entries(registry)) {
      assert.equal(factory({}).channel, channel);
      assert.equal(new factory({}).channel, channel);
    }
  });

  test('createNotifier rejects inherited object keys as unknown channels', () => {
    for (const name of ['constructor', 'toString', '__proto__', 'hasOwnProperty']) {
      assert.throws(() => createNotifier(name), /unknown notification channel/);
    }
  });

  test('options.channel cannot rename a notifier', async () => {
    const log = [];
    const notifier = createNotifier('sms', { channel: 'email', transport: recordingTransport(log) });
    const result = await notifier.send(validUsers.sms, { title: 'T', body: 'B' });

    assert.equal(notifier.channel, 'sms');
    assert.equal(result.channel, 'sms');
    assert.equal(log[0].channel, 'sms');
  });

  test('createAllNotifiers shares one throttle store without mixing channels', async () => {
    const throttleStore = new Map();
