const NOW = '2026-01-02T03:00:00.000Z';
const HOUR_MS = 60 * 60 * 1000;

const validUsers = {
  email: { id: 'u1', name: 'Ava', email: 'ava@example.com', emailOptIn: true },
  sms: { id: 'u2', phone: '+15551234567', smsOptIn: true },
  slack: { id: 'u3', slackId: 'U123' },
  inapp: { id: 'u4', name: 'Dee' }
};

function recordingTransport(log = []) {
  const transport = {};
  for (const channel of Object.keys(validUsers)) {
    transport[channel] = async function deliver(payload) {
      log.push({ channel, payload, receiver: this });
    };
  }
  return transport;
}

function fixedClock(iso = NOW) {
  let current = Date.parse(iso);
  return {
    now: () => new Date(current),
    advance: ms => { current += ms; }
  };
}

