describe('shared validation', () => {
  // Per channel, to catch a channel check running before the shared user checks.
  const userCases = [
    ['missing user', null, /^user is required$/],
    ['non-object user', 'u1', /^user is required$/],
    ['empty user id', { id: '' }, /user\.id is required/]
  ];

  for (const channel of Object.keys(validUsers)) {
    for (const [name, user, expected] of userCases) {
      test(`${channel} rejects ${name}`, async () => {
        const notifier = createNotifier(channel, { transport: recordingTransport() });
        await assert.rejects(() => notifier.send(user, { title: 'T', body: 'B' }), { name: 'TypeError', message: expected });
      });
    }
  }

  const messageCases = [
    ['missing message', null, /^message is required$/],
    ['non-object message', 'hello', /^message is required$/],
    ['empty title', { title: '', body: 'B' }, /message\.title and message\.body are required/],
    ['missing body', { title: 'T' }, /message\.title and message\.body are required/]
  ];

  for (const [name, message, expected] of messageCases) {
    test(`rejects ${name}`, async () => {
      const notifier = createNotifier('sms', { transport: recordingTransport() });
      await assert.rejects(() => notifier.send(validUsers.sms, message), { name: 'TypeError', message: expected });
    });
  }

  test('channel user checks run after the shared checks', async () => {
    const checks = [
      ['email', { id: 'u1', email: 'not-an-address' }, /user\.email is required/],
      ['sms', { id: 'u2', phone: '+0123456789' }, /E\.164/],
      ['slack', { id: 'u3' }, /slackId or user\.slackChannel/],
      ['inapp', { id: 'u4', disabledInApp: true }, /disabled for this user/]
    ];
    for (const [channel, user, expected] of checks) {
      const notifier = createNotifier(channel, { transport: recordingTransport() });
      await assert.rejects(() => notifier.send(user, { title: 'T', body: 'B' }), { name: 'TypeError', message: expected });
      await assert.rejects(() => notifier.send({ email: 'a@b' }, { title: 'T', body: 'B' }), /user\.id is required/);
    }
  });
});

describe('throttling', () => {
  const defaultLimits = { email: 8, sms: 4, slack: 20, inapp: 50 };

  for (const [channel, limit] of Object.entries(defaultLimits)) {
    test(`${channel} allows ${limit} sends per hour by default`, async () => {
      const notifier = createNotifier(channel, { transport: recordingTransport(), now: fixedClock().now });
      const message = { title: 'T', body: 'B' };

      for (let sent = 0; sent < limit; sent++) {
        assert.equal((await notifier.send(validUsers[channel], message)).status, 'sent');
      }
  });
});

describe('delivery', () => {
  const transportNames = { email: 'email', sms: 'sms', slack: 'slack', inapp: 'in-app' };

  for (const [channel, name] of Object.entries(transportNames)) {
    test(`${channel} rejects without a ${name} transport and records nothing`, async () => {
      for (const transport of [undefined, { [channel]: 'not a function' }]) {
        const throttleStore = new Map();
        const notifier = createNotifier(channel, { transport, throttleStore });

        await assert.rejects(
          () => notifier.send(validUsers[channel], { title: 'T', body: 'B' }),
          { name: 'Error', message: `${name} transport is not configured` }
        );
        assert.equal(throttleStore.size, 0);
      }
    });
  }

  test('throttled sends do not require a configured transport', async () => {
    const notifier = createNotifier('email', { now: fixedClock().now });
    const result = await notifier.send({ id: 'e1', email: 'e@example.com' }, { title: 'T', body: 'B', category: 'marketing' });

    assert.equal(result.status, 'throttled');
  });

  test('a failed transport call is not counted toward the limit', async () => {
    const throttleStore = new Map();
    const transport = { sms: async () => { throw new Error('gateway down'); } };
    const notifier = createNotifier('sms', { transport, throttleStore, maxPerHour: 1 });

    await assert.rejects(() => notifier.send(validUsers.sms, { title: 'T', body: 'B' }), /gateway down/);
    assert.equal(throttleStore.size, 0);
  });

  test('transport methods are called on the transport object', async () => {
    const log = [];
    const transport = recordingTransport(log);
    for (const channel of Object.keys(validUsers)) {
      await createNotifier(channel, { transport }).send(validUsers[channel], { title: 'T', body: 'B' });
    }

    assert.equal(log.length, 4);
    assert.ok(log.every(entry => entry.receiver === transport));
  });
});

describe('payload formatting', () => {
  async function payloadFor(channel, user, message, sendOptions, notifierOptions = {}) {
    const log = [];
    const notifier = createNotifier(channel, { transport: recordingTransport(log), now: fixedClock().now, ...notifierOptions });
    const result = await notifier.send(user, message, sendOptions);
    return { result, payload: log[0].payload };
  }

  test('channel settings options replace their defaults', async () => {
    const email = await payloadFor('email', validUsers.email, { title: 'T', body: 'B', category: 'digest' }, {}, {
      replyTo: 'help@example.com',
      unsubscribeBaseUrl: 'https://mail.example.com/stop'
    });
    const sms = await payloadFor('sms', validUsers.sms, { title: 'T', body: 'B' }, {}, { senderId: 'ACME' });
    const slack = await payloadFor('slack', validUsers.slack, { title: 'T', body: 'B' }, {}, { defaultChannel: '#ops' });
    const inapp = await payloadFor('inapp', validUsers.inapp, { title: 'T', body: 'B' }, {}, { defaultIcon: 'star', defaultAction: '/inbox' });

    assert.equal(email.payload.replyTo, 'help@example.com');
    assert.match(email.payload.text, /https:\/\/mail\.example\.com\/stop\?user=u1\.$/);
    assert.equal(sms.payload.from, 'ACME');
    assert.equal(slack.payload.channel, '#ops');
    assert.equal(inapp.payload.icon, 'star');
    assert.equal(inapp.payload.actionUrl, '/inbox');
  });

  test('shared fields fill templates, resolve locale, and default metadata', async () => {
    const { payload } = await payloadFor('inapp', { id: 'u9', locale: 'fr-FR' }, { title: 'Hi {{name}}', body: '{{id}} {{id}} {{category}}' });

    assert.equal(payload.id, `inapp-u9-${Date.parse(NOW)}`);
    assert.equal(payload.title, 'Hi there');
    assert.equal(payload.segments, 1);
    assert.equal(long.payload.text.length, 140);
    assert.ok(long.payload.text.endsWith('x…'));
  });

  test('Slack payload channel is the destination while the send result keeps "slack"', async () => {
    const { payload, result } = await payloadFor('slack', { id: 'u3', slackChannel: '#alerts' }, { title: 'Deploy', body: 'Done' });

    assert.equal(result.channel, 'slack');
    assert.equal(payload.channel, '#alerts');
    assert.equal(payload.workspace, 'main');
    assert.equal(payload.threadTs, null);
    assert.equal(payload.text, '*Deploy*\nDone');
    assert.equal(payload.preview, 'Deploy\nDone');
    assert.equal(payload.blocks[2].elements[0].text, 'Category: general');

    const fallback = await payloadFor('slack', { id: 'u3', slackId: 'U1' }, { title: 'T', body: 'B' });
    assert.equal(fallback.payload.channel, '#general');

    const mentioned = await payloadFor('slack', { id: 'u3', slackId: 'U1', slackWorkspace: 'eng' }, { title: 'T', body: 'B' });
    assert.equal(mentioned.payload.workspace, 'eng');
    assert.equal(mentioned.payload.blocks[0].text.text, '<@U1> *T*');
  });

  test('in-app expiry depends on priority unless expiresInHours is given', async () => {
    const urgent = await payloadFor('inapp', validUsers.inapp, { title: 'T', body: 'B', priority: 'urgent', icon: 'star', actionUrl: '/m' });
    const custom = await payloadFor('inapp', validUsers.inapp, { title: 'T', body: 'B', actionUrl: '/m' }, { expiresInHours: 2, actionUrl: '/o' });
    const plain = await payloadFor('inapp', validUsers.inapp, { title: 'T', body: 'B' });

    assert.equal(urgent.payload.expiresAt, '2026-01-05T03:00:00.000Z');
    assert.equal(urgent.payload.icon, 'star');
    assert.equal(urgent.payload.actionUrl, '/m');
    assert.equal(urgent.result.preview, 'T');
    assert.equal(urgent.payload.metadata.priority, 'urgent');
    assert.equal(custom.payload.expiresAt, '2026-01-02T05:00:00.000Z');
    assert.equal(custom.payload.icon, 'bell');
    assert.equal(custom.payload.actionUrl, '/o');
    assert.equal(plain.payload.actionUrl, '/notifications');
  });
});
